The robot's heading is 10° and the target's angle is 350°. What does it print when the difference is wrapped?

```
float aciFarki(float hedef, float simdiki) {
  float f = hedef - simdiki;
  while (f > 180) f -= 360;
  while (f < -180) f += 360;
  return f;
}

void setup() {
  Serial.begin(9600);
  Serial.println(aciFarki(350, 10), 0);
}

void loop() {}
